files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --muted: #8a8a9a;
  --focus: #f9c74f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent);
}

.clock-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.clock {
  font-family: 'Courier New', Courier, monospace;
  font-size: 3rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text);
  text-shadow: 0 0 8px var(--accent);
  line-height: 1.2;
  word-break: break-all;
}

.ampm {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: 0.1em;
}

.controls {
  display: flex;
  justify-content: center;
  width: 100%;
}

.toggle-label {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  font-size: 1rem;
  color: var(--text);
  padding: 8px 12px;
  border-radius: 8px;
  transition: background 0.2s;
}

.toggle-label:hover {
  background: rgba(233, 69, 96, 0.15);
}

.toggle-label:focus-within {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.toggle-label input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-switch {
  position: relative;
  width: 48px;
  height: 26px;
  background: var(--muted);
  border-radius: 13px;
  transition: background 0.2s;
  flex-shrink: 0;
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  background: var(--text);
  border-radius: 50%;
  transition: transform 0.2s;
}

.toggle-label input:checked + .toggle-switch {
  background: var(--accent);
}

.toggle-label input:checked + .toggle-switch::after {
  transform: translateX(22px);
}

.toggle-label input:active + .toggle-switch {
  transform: scale(0.95);
}

.lap-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding-top: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  width: 100%;
}

.lap-label {
  font-size: 0.875rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.lap {
  font-family: 'Courier New', Courier, monospace;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.05em;
}

@media (max-width: 400px) {
  .clock {
    font-size: 2.25rem;
  }
  .card {
    padding: 24px 16px;
  }
}

@media (max-width: 360px) {
  .clock {
    font-size: 1.75rem;
  }
  .lap {
    font-size: 1.25rem;
  }
}

(function () {
  'use strict';

  const clockEl = document.getElementById('clock');
  const ampmEl = document.getElementById('ampm');
  const toggle = document.getElementById('format-toggle');
  const lapEl = document.getElementById('lap');

  const startTime = Date.now();
  let use24Hour = true;

  function pad(n) {
    return n < 10 ? '0' + n : String(n);
  }

  function formatClock(date) {
    let hours = date.getHours();
    const minutes = date.getMinutes();
    const seconds = date.getSeconds();
    let suffix = '';

    if (!use24Hour) {
      suffix = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12;
      if (hours === 0) hours = 12;
    }

    return {
      time: pad(hours) + ':' + pad(minutes) + ':' + pad(seconds),
      suffix: suffix
    };
  }

  function formatLap(ms) {
    const totalSeconds = Math.floor(ms / 1000);
    const h = Math.floor(totalSeconds / 3600);
    const m = Math.floor((totalSeconds % 3600) / 60);
    const s = totalSeconds % 60;
    return pad(h) + ':' + pad(m) + ':' + pad(s);
  }

  function tick() {
    const now = new Date();
    const formatted = formatClock(now);
    clockEl.textContent = formatted.time;

    if (formatted.suffix) {
      ampmEl.textContent = formatted.suffix;
      ampmEl.hidden = false;
    } else {
      ampmEl.hidden = true;
    }

    lapEl.textContent = formatLap(Date.now() - startTime);
  }

  function updateToggleState() {
    use24Hour = toggle.checked;
    toggle.setAttribute('aria-checked', String(use24Hour));
    tick();
  }

  toggle.addEventListener('change', updateToggleState);

  // Initialize
  toggle.checked = true;
  updateToggleState();
  setInterval(tick, 1000);
})();
